package choucisan

import (
	"fmt"
	"math"
	"math/rand"
	"time"
)

// RetryConfig holds configuration for the retry mechanism.
type RetryConfig struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration
	Multiplier  float64
	Jitter      bool
}

// DefaultRetryConfig returns a sensible default configuration.
func DefaultRetryConfig() RetryConfig {
	return RetryConfig{
		MaxAttempts: 5,
		BaseDelay:   100 * time.Millisecond,
		MaxDelay:    10 * time.Second,
		Multiplier:  2.0,
		Jitter:      true,
	}
}

// RetryableError wraps an error to indicate whether a retry is appropriate.
type RetryableError struct {
	Err        error
	Retryable  bool
}

func (e *RetryableError) Error() string { return e.Err.Error() }
func (e *RetryableError) Unwrap() error { return e.Err }

// RetryWithBackoff calls fn up to cfg.MaxAttempts times, applying exponential
// backoff with optional jitter between attempts. It returns the first
// successful result or the last error encountered.
//
// If fn returns a *RetryableError with Retryable=false, the error is returned
// immediately without further retries.
func RetryWithBackoff[T any](cfg RetryConfig, fn func() (T, error)) (T, error) {
	var zero T
	var lastErr error

	for attempt := 0; attempt < cfg.MaxAttempts; attempt++ {
		result, err := fn()
		if err == nil {
			return result, nil
		}

		lastErr = err

		// Check if the error explicitly says not to retry.
		var re *RetryableError
		if asErr, ok := err.(*RetryableError); ok {
			re = asErr
		}
		if re != nil && !re.Retryable {
			return zero, err
		}

		// Don't sleep after the last attempt.
		if attempt == cfg.MaxAttempts-1 {
			break
		}

		delay := cfg.backoffDelay(attempt)
		time.Sleep(delay)
	}

	return zero, fmt.Errorf("all %d attempts failed; last error: %w", cfg.MaxAttempts, lastErr)
}

// backoffDelay calculates the delay for a given attempt number.
func (cfg RetryConfig) backoffDelay(attempt int) time.Duration {
	delay := float64(cfg.BaseDelay) * math.Pow(cfg.Multiplier, float64(attempt))
	if delay > float64(cfg.MaxDelay) {
		delay = float64(cfg.MaxDelay)
	}
	if cfg.Jitter {
		// Add up to 25% random jitter.
		jitter := delay * 0.25 * rand.Float64()
		delay += jitter
	}
	return time.Duration(delay)
}

package choucisan

import (
	"errors"
	"fmt"
	"testing"
	"time"
)

func TestRetryWithBackoff_Success(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 3,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	result, err := RetryWithBackoff(cfg, func() (int, error) {
		return 42, nil
	})
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if result != 42 {
		t.Fatalf("expected 42, got %d", result)
	}
}

func TestRetryWithBackoff_EventuallySucceeds(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 5,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	attempts := 0
	result, err := RetryWithBackoff(cfg, func() (string, error) {
		attempts++
		if attempts < 3 {
			return "", errors.New("transient failure")
		}
		return "ok", nil
	})
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if result != "ok" {
		t.Fatalf("expected 'ok', got %q", result)
	}
	if attempts != 3 {
		t.Fatalf("expected 3 attempts, got %d", attempts)
	}
}

func TestRetryWithBackoff_ExhaustsAttempts(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 3,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	attempts := 0
	_, err := RetryWithBackoff(cfg, func() (int, error) {
		attempts++
		return 0, errors.New("permanent failure")
	})
	if err == nil {
		t.Fatal("expected an error, got nil")
	}
	if attempts != 3 {
		t.Fatalf("expected 3 attempts, got %d", attempts)
	}
}

func TestRetryWithBackoff_NonRetryableError(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 5,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	attempts := 0
	_, err := RetryWithBackoff(cfg, func() (int, error) {
		attempts++
		return 0, &RetryableError{
			Err:       errors.New("unauthorized"),
			Retryable: false,
		}
	})
	if err == nil {
		t.Fatal("expected an error, got nil")
	}
	if attempts != 1 {
		t.Fatalf("expected 1 attempt (non-retryable), got %d", attempts)
	}
}

func TestRetryWithBackoff_RetryableError(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 3,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	attempts := 0
	_, err := RetryWithBackoff(cfg, func() (int, error) {
		attempts++
		return 0, &RetryableError{
			Err:       errors.New("rate limited"),
			Retryable: true,
		}
	})
	if err == nil {
		t.Fatal("expected an error, got nil")
	}
	if attempts != 3 {
		t.Fatalf("expected 3 attempts (retryable), got %d", attempts)
	}
}

func TestRetryWithBackoff_ContextPreserved(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 3,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	type result struct {
		ID   int
		Name string
	}

	attempts := 0
	res, err := RetryWithBackoff(cfg, func() (result, error) {
		attempts++
		if attempts < 2 {
			return result{}, fmt.Errorf("not ready yet")
		}
		return result{ID: 7, Name: "seven"}, nil
	})
	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if res.ID != 7 || res.Name != "seven" {
		t.Fatalf("unexpected result: %+v", res)
	}
}

func TestRetryWithBackoff_ZeroValueOnError(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 2,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	res, err := RetryWithBackoff(cfg, func() (string, error) {
		return "partial", errors.New("failed")
	})
	if err == nil {
		t.Fatal("expected error")
	}
	if res != "" {
		t.Fatalf("expected zero value string on error, got %q", res)
	}
}

func TestRetryWithBackoff_SingleAttempt(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 1,
		BaseDelay:   10 * time.Millisecond,
		MaxDelay:    100 * time.Millisecond,
		Multiplier:  2.0,
		Jitter:      false,
	}

	attempts := 0
	_, err := RetryWithBackoff(cfg, func() (int, error) {
		attempts++
		return 0, errors.New("only try once")
	})
	if err == nil {
		t.Fatal("expected error")
	}
	if attempts != 1 {
		t.Fatalf("expected 1 attempt, got %d", attempts)
	}
}

func TestRetryWithBackoff_Timing(t *testing.T) {
	cfg := RetryConfig{
		MaxAttempts: 4,
		BaseDelay:   50 * time.Millisecond,
		MaxDelay:    1 * time.Second,
		Multiplier:  2.0,
		Jitter:      false,
	}

	start := time.Now()
	RetryWithBackoff(cfg, func() (int, error) {
		return 0, errors.New("fail")
	})
	elapsed := time.Since(start)

	// With no jitter and delays of 50, 100, 200ms between 4 attempts,
	// total delay should be ~350ms. Allow generous tolerance.
	if elapsed < 300*time.Millisecond {
		t.Fatalf("expected at least 300ms elapsed, got %v", elapsed)
	}
}

func TestDefaultRetryConfig(t *testing.T) {
	cfg := DefaultRetryConfig()
	if cfg.MaxAttempts != 5 {
		t.Fatalf("expected 5 max attempts, got %d", cfg.MaxAttempts)
	}
	if cfg.BaseDelay != 100*time.Millisecond {
		t.Fatalf("expected 100ms base delay, got %v", cfg.BaseDelay)
	}
	if cfg.Multiplier != 2.0 {
		t.Fatalf("expected 2.0 multiplier, got %f", cfg.Multiplier)
	}
	if !cfg.Jitter {
		t.Fatal("expected jitter to be enabled by default")
	}
}
